```python
from abc import ABC, abstractmethod

class Base(ABC):
    @abstractmethod
    def a(self): ...
    @abstractmethod
    def b(self): ...

class Mid(Base):
    def a(self): return 1

class Leaf(Mid):
    def b(self): return 2

print(Leaf().a() + Leaf().b())
try:
    Mid()
except TypeError:
    print("TypeError")
```
